import React, { useState } from 'react';
import { useAuth } from '../../context/AuthContext';
import Button from '../../components/common/Button/Button';
import Input from '../../components/common/Input/Input';
import PasswordInput from '../../components/common/PasswordInput/PasswordInput';
import ToggleButton from '../../components/common/ToggleButton/ToggleButton';
import styles from './ProfilePage.module.css';

const ProfilePage = () => {
    const { user, updateProfile, changePassword, deleteAccount, logout } = useAuth();
    const [showSettings, setShowSettings] = useState(false);
    const [profile, setProfile] = useState({
        name: user?.name || '', email: user?.email || '', phone: user?.phone || '',
        gameLevel: user?.gameLevel || 'D2', language: user?.language || 'ru', theme: user?.theme || 'light'
    });
    const [passwords, setPasswords] = useState({ current: '', new: '', confirm: '' });
    const [loading, setLoading] = useState(false);
    const [message, setMessage] = useState({ text: '', type: '' });
    const levels = ['D1', 'D2', 'D3', 'D4', 'D4Plus'];

    const handleSaveProfile = async (e) => {
        e.preventDefault();
        setLoading(true);
        try {
            await updateProfile(profile);
            setMessage({ text: 'Профиль успешно обновлен', type: 'success' });
        } catch (err) {
            setMessage({ text: err.message || 'Ошибка обновления', type: 'error' });
        } finally { setLoading(false); }
    };

    const handleChangePassword = async (e) => {
        e.preventDefault();
        if (passwords.new !== passwords.confirm) {
            setMessage({ text: 'Новый пароль и подтверждение не совпадают', type: 'error' });
            return;
        }
        setLoading(true);
        try {
            await changePassword({ currentPassword: passwords.current, newPassword: passwords.new });
            setMessage({ text: 'Пароль успешно изменен', type: 'success' });
            setPasswords({ current: '', new: '', confirm: '' });
        } catch (err) {
            setMessage({ text: err.message || 'Ошибка смены пароля', type: 'error' });
        } finally { setLoading(false); }
    };

    const handleDeleteAccount = async () => {
        if (window.confirm('Вы уверены? Это действие необратимо!')) await deleteAccount();
    };

    return (
        <div className={styles.profilePage}>
            <div className={styles.container}>
                <div className={styles.profileCard}>
                    <div className={styles.header}>
                        <h1 className={styles.title}>Личный кабинет</h1>
                        <button className={styles.settingsButton} onClick={() => setShowSettings(!showSettings)}>⚙️</button>
                    </div>
                    <div className={styles.content}>
                        {message.text && <div className={`${styles.message} ${styles[message.type]}`}>{message.text}</div>}
                        <form onSubmit={handleSaveProfile} className={styles.form}>
                            <Input label="Имя" value={profile.name} onChange={(e) => setProfile({...profile, name: e.target.value})} required />
                            <Input label="Email" type="email" value={profile.email} onChange={(e) => setProfile({...profile, email: e.target.value})} required />
                            <Input label="Телефон" placeholder="+375 29 123-45-67" value={profile.phone} onChange={(e) => setProfile({...profile, phone: e.target.value})} />
                            <div className={styles.levelSection}>
                                <label className={styles.label}>Уровень игры</label>
                                <div className={styles.levelButtons}>
                                    {levels.map(level => (<ToggleButton key={level} label={level === 'D4Plus' ? 'D4+' : level} isActive={profile.gameLevel === level} onClick={() => setProfile({...profile, gameLevel: level})} />))}
                                </div>
                            </div>
                            <Button type="submit" fullWidth loading={loading}>Сохранить изменения</Button>
                        </form>
                        <form onSubmit={handleChangePassword} className={styles.passwordForm}>
                            <h3 className={styles.sectionTitle}>Смена пароля</h3>
                            <PasswordInput label="Текущий пароль" value={passwords.current} onChange={(e) => setPasswords({...passwords, current: e.target.value})} required />
                            <PasswordInput label="Новый пароль" value={passwords.new} onChange={(e) => setPasswords({...passwords, new: e.target.value})} required />
                            <PasswordInput label="Подтверждение пароля" value={passwords.confirm} onChange={(e) => setPasswords({...passwords, confirm: e.target.value})} required />
                            <Button type="submit" variant="secondary" fullWidth>Изменить пароль</Button>
                        </form>
                        {showSettings && (
                            <div className={styles.settingsPanel}>
                                <h3 className={styles.sectionTitle}>Настройки</h3>
                                <div className={styles.settingItem}>
                                    <span>🌐 Язык</span>
                                    <div className={styles.settingControls}>
                                        <ToggleButton label="Русский" isActive={profile.language === 'ru'} onClick={() => setProfile({...profile, language: 'ru'})} />
                                        <ToggleButton label="English" isActive={profile.language === 'en'} onClick={() => setProfile({...profile, language: 'en'})} />
                                    </div>
                                </div>
                                <div className={styles.settingItem}>
                                    <span>🎨 Тема</span>
                                    <div className={styles.settingControls}>
                                        <ToggleButton label="Светлая" isActive={profile.theme === 'light'} onClick={() => setProfile({...profile, theme: 'light'})} />
                                        <ToggleButton label="Темная" isActive={profile.theme === 'dark'} onClick={() => setProfile({...profile, theme: 'dark'})} />
                                    </div>
                                </div>
                            </div>
                        )}
                        <div className={styles.actions}>
                            <Button variant="secondary" onClick={logout}>Сменить пользователя</Button>
                            <Button variant="danger" onClick={handleDeleteAccount}>Удалить аккаунт</Button>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default ProfilePage;
